const sheetsData = $('Read Sheets Changes').all().map(i => i.json);
const dbData = $('Read DB Records').all().map(i => i.json);

// Build lookup maps by ID
const sheetsMap = {};
sheetsData.forEach(row => { sheetsMap[row.id] = row; });
const dbMap = {};
dbData.forEach(row => { dbMap[row.id] = row; });

const toUpsertInDB = [];
const toUpdateInSheets = [];
const conflicts = [];

// Sheets → DB: find new or updated in Sheets
for (const [id, sheetRow] of Object.entries(sheetsMap)) {
  const dbRow = dbMap[id];
  if (!dbRow) {
    toUpsertInDB.push({ ...sheetRow, source: 'sheets_new' });
  } else if (sheetRow.updated_at > dbRow.updated_at) {
    toUpsertInDB.push({ ...sheetRow, source: 'sheets_updated' });
  } else if (dbRow.updated_at > sheetRow.updated_at) {
    toUpdateInSheets.push({ ...dbRow, source: 'db_updated' });
  } else if (sheetRow.name !== dbRow.name || sheetRow.email !== dbRow.email) {
    conflicts.push({
      id: id,
      sheets_data: sheetRow,
      db_data: dbRow,
      reason: 'Both modified with same timestamp'
    });
  }
}

// DB → Sheets: find records only in DB
for (const [id, dbRow] of Object.entries(dbMap)) {
  if (!sheetsMap[id]) {
    toUpdateInSheets.push({ ...dbRow, source: 'db_only' });
  }
}

return [{
  json: {
    upsert_to_db: toUpsertInDB,
    update_in_sheets: toUpdateInSheets,
    conflicts: conflicts,
    db_upsert_count: toUpsertInDB.length,
    sheets_update_count: toUpdateInSheets.length,
    conflict_count: conflicts.length,
    sync_timestamp: new Date().toISOString()
  }
}];
